processor-info.script:

			String cmd = input.getText("cmd");

			if("GET_OFFLINE_EDU_LIST".equals(cmd) )
			{
				StringBuffer addWhere = new StringBuffer();

                //지회코드  
                String search_gbn_jicode = input.getText("search_gbn_jicode") ;

                if ( search_gbn_jicode !=null && !search_gbn_jicode.equals("%") )
                {
                    addWhere.append(" and a.ji_code = '" + search_gbn_jicode + "' ");
                }
                input.put("addWhere", addWhere.toString() );
              	executeSQL(cmd, connection, input, output);
             }else if( "GET_OFFLINE_USER_LIST".equals(cmd) || "GET_OFFLINE_USER_HISTORY".equals(cmd) ){

             	if( "GET_OFFLINE_USER_LIST".equals(cmd) )
             		input.put("addWhere", " and a.dcm_no = '" + input.getText("dcm_no")+ "' " );

             	if( "GET_OFFLINE_USER_HISTORY".equals(cmd) &&  "2".equals(input.getText("confirm_step")) )
             		input.put("addWhere", " and a.jcode = '" + input.getText("jcode")+ "' " );	

              	executeSQL("GET_OFFLINE_USER_LIST", connection, input, output);

             }else{
				executeSQL(cmd, connection, input, output);
			}
